import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M6 2h4V0H6zm-6 8V6h2v4zM1 0h3v2H2v2H0V1a1 1 0 0 1 1-1M0 14v1a1 1 0 0 0 1 1h3v-2H2v-2H0zm10 0v2H6v-2zm6-8h-2v4h2zm-1 10h-3v-2h2v-2h2v3a1 1 0 0 1-1 1m1-14V1a1 1 0 0 0-1-1h-3v2h2v2h2zM7 5a1 1 0 0 1 2 0v2h2a1 1 0 1 1 0 2H9v2a1 1 0 1 1-2 0V9H5a1 1 0 0 1 0-2h2z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M2 0h3v2H2v3H0V1a1 1 0 0 1 1-1zm16 18v-3h2v4a1 1 0 0 1-1 1h-4v-2zM0 15v4a1 1 0 0 0 1 1h4v-2H2v-3zM18 0h-3v2h3v3h2V1a1 1 0 0 0-1-1zm-6 0H8v2h4zM0 8v4h2V8zm9-2a1 1 0 0 1 2 0v3h3a1 1 0 1 1 0 2h-3v3a1 1 0 1 1-2 0v-3H6a1 1 0 1 1 0-2h3zm11 6h-2V8h2zM8 20v-2h4v2z"] as readonly string[];

export const SelectionBoxAddIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="selection-box-add" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
SelectionBoxAddIcon.displayName = `Blueprint6.Icon.SelectionBoxAddIcon`;

/**
 * @deprecated Use {@link SelectionBoxAddIcon} instead.
 */
export const SelectionBoxAdd: typeof SelectionBoxAddIcon = SelectionBoxAddIcon;

export default SelectionBoxAddIcon;
